import{_ as c,C as r,o as n,c as h,j as d,a as e,E as o,a5 as l}from"./chunks/framework.CyyS6Zdm.js";const w=JSON.parse('{"title":"下载触发器","description":"","frontmatter":{},"headers":[],"relativePath":"components/download-trigger.md","filePath":"components/download-trigger.md","lastUpdated":1787185306000}'),s={name:"components/download-trigger.md"},b={id:"下载触发器",tabindex:"-1"};function g(p,t,u,m,x,q){const i=r("Badge"),a=r("XhDemo");return n(),h("div",null,[d("h1",b,[t[0]||(t[0]=e("下载触发器 ",-1)),o(i,{type:"info",text:"download-trigger"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#下载触发器","aria-label":'Permalink to "下载触发器 <Badge type="info" text="download-trigger" />"'},"​",-1))]),t[3]||(t[3]=l('<p>把一段数据交给浏览器下载，并把取数这段过程如实报出来。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>内容已经在前端手里：当前表格导出成 CSV、编辑器里的草稿存成文件、生成好的配置文本。</li><li>数据要点了才算：交一个取数函数，点下去才发请求或才开始序列化。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>文件在服务端且有稳定地址：直接写一个 <code>&lt;a href download&gt;</code> 指过去，让服务端决定文件名与类型，别在前端造一份副本。</li><li>内容只是要带走一小段文字：用<a href="./clipboard">剪贴板</a>，用户不必再去下载目录里翻。</li><li>方向反过来是把文件交进来：用<a href="./file-upload">文件上传</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>数据可以是文本、Blob，或点了才调用的取数函数（可返回 Promise）。</li><li>取数在途时状态是 <code>preparing</code>，此时再点不会重复发起；无论成败都回到 <code>idle</code>，界面上不留&quot;下载中&quot;的假象。</li><li>失败会说出来：取数抛出、拒绝，或环境造不出下载，都走 <code>onDownloadError</code> 并带上原始原因。</li><li>文件名与类型在发起那一刻定死，取数途中宿主改了 prop 也不影响这一次写出的那份。</li><li>Vue 侧默认插槽拿得到 <code>{ status, preparing, disabled, fileName, download }</code>，可据 <code>preparing</code> 换掉按钮上的文字；Web Components 侧按钮内容由作者自己写，要跟着状态换文字得自己盯 <code>data-state</code>。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>内容已经在手里就直接给字符串，点一下即交给浏览器；文件名连同扩展名都由 file-name 说了算</p>',10)),o(a,{src:"download-trigger/01-basic"}),t[4]||(t[4]=d("h3",{id:"按需取数",tabindex:"-1"},[e("按需取数 "),d("a",{class:"header-anchor",href:"#按需取数","aria-label":'Permalink to "按需取数"'},"​")],-1)),t[5]||(t[5]=d("p",null,"data 给函数就是点了才算：它可以返回 Promise，这段时间状态是 preparing，再点也不会重复取一遍",-1)),o(a,{src:"download-trigger/02-lazy"}),t[6]||(t[6]=d("h3",{id:"blob-内容",tabindex:"-1"},[e("Blob 内容 "),d("a",{class:"header-anchor",href:"#blob-内容","aria-label":'Permalink to "Blob 内容"'},"​")],-1)),t[7]||(t[7]=d("p",null,"结构化与二进制内容交 Blob，它自带的类型就是写出去的类型；显式写了 mime-type 则以 mime-type 为准",-1)),o(a,{src:"download-trigger/03-blob"}),t[8]||(t[8]=d("h3",{id:"失败要说出来",tabindex:"-1"},[e("失败要说出来 "),d("a",{class:"header-anchor",href:"#失败要说出来","aria-label":'Permalink to "失败要说出来"'},"​")],-1)),t[9]||(t[9]=d("p",null,'取数抛出或拒绝都会退回 idle 并派 download-error，按钮不会一直停在"下载中"',-1)),o(a,{src:"download-trigger/04-error"}),t[10]||(t[10]=d("h3",{id:"禁用",tabindex:"-1"},[e("禁用 "),d("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),t[11]||(t[11]=d("p",null,"禁用的触发器不可聚焦也点不动，连取数函数都不会被调用",-1)),o(a,{src:"download-trigger/05-disabled"}),t[12]||(t[12]=l('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-download-trigger&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhDownloadTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useDownloadTrigger</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/download-trigger.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;download-trigger&quot;</code>：<strong><code>root</code></strong></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>data</code></td><td><code>DownloadTriggerData</code></td><td></td><td>要下载的内容：文本、Blob，或点下去才调用的取数函数（可返回 Promise）。</td></tr><tr><td><code>fileName</code></td><td><code>string</code></td><td></td><td>写出的文件名；缺省或空串退回内建默认名。</td></tr><tr><td><code>mimeType</code></td><td><code>string</code></td><td></td><td>内容类型；给了它就以它为准，连 Blob 自带的类型也照它重包一次。缺省时文本按纯文本处理。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>禁用：按钮不可聚焦、点不动。</td></tr><tr><td><code>onDownloadComplete</code></td><td><code>(details: DownloadTriggerCompleteDetails) =&gt; void</code></td><td></td><td>数据已交给浏览器时通知一次。到这里只说明下载已经发起，浏览器把文件写没写到盘上组件看不见。</td></tr><tr><td><code>onDownloadError</code></td><td><code>(details: DownloadTriggerErrorDetails) =&gt; void</code></td><td></td><td>取数失败或造不出下载时通知；此刻状态已经回到 idle。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>download-complete</code></td><td><code>DownloadTriggerCompleteDetails</code></td><td>数据已交给浏览器；detail 为 <code>{ fileName }</code></td></tr><tr><td><code>download-error</code></td><td><code>DownloadTriggerErrorDetails</code></td><td>取数失败或造不出下载；detail 为 <code>{ error, fileName }</code>，此刻状态已经回到 idle</td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhDownloadTrigger</code></td><td><code>default</code></td><td><code>DownloadTriggerSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>state.get()</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>事件</strong>：<code>DOWNLOAD.TRIGGER</code> · <code>DOWNLOAD.SUCCESS</code> · <code>DOWNLOAD.ERROR</code></p><p><strong>判据</strong>：<code>isDisabled</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useDownloadTrigger</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>status</code></td><td><code>DownloadTriggerStatus</code></td><td></td></tr><tr><td><code>preparing</code></td><td><code>boolean</code></td><td>数据还在取。按钮不因此变禁用，只是这段时间里再点不会重复发起。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>fileName</code></td><td><code>string</code></td><td>这一次会写出的文件名（prop 缺省时是内建默认名）。</td></tr><tr><td><code>download</code></td><td><code>() =&gt; void</code></td><td>走一次下载意图，与点按钮同一条路：禁用时不动，取数在途时不重复发起。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/button/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in root, 未禁用</td><td>发起一次下载；取数在途时这两个键同样不会重复发起</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-busy</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr></tbody></table><ul><li>触发器是原生 <code>&lt;button type=&quot;button&quot;&gt;</code>，Enter 与 Space 的激活由平台负责。</li><li>取数在途时按钮不变成禁用，只挂 <code>aria-busy=&quot;true&quot;</code>：禁用会把焦点从按钮上弹走，键盘用户等回来时不知道自己在哪。</li><li>按钮上的文字要说清楚下的是什么（&quot;导出 CSV&quot;而不是&quot;下载&quot;），读屏一次只念一个按钮，光有图标听不出区别。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/download-trigger.css</code> 按部件选择：<code>[data-scope=&quot;download-trigger&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>state.get()</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-download-trigger-bg</code> · <code>--xh-download-trigger-bg-active</code> · <code>--xh-download-trigger-bg-disabled</code> · <code>--xh-download-trigger-bg-hover</code> · <code>--xh-download-trigger-border</code> · <code>--xh-download-trigger-border-disabled</code> · <code>--xh-download-trigger-border-hover</code> · <code>--xh-download-trigger-fg</code> · <code>--xh-download-trigger-font-size</code> · <code>--xh-download-trigger-font-weight</code> · <code>--xh-download-trigger-gap</code> · <code>--xh-download-trigger-h</code> · <code>--xh-download-trigger-px</code> · <code>--xh-download-trigger-radius</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>与<a href="./button">按钮</a>是两件事：按钮带形态/语气/尺寸三轴，下载触发器只管行为，自带的是一份中性按钮外观（高度、描边、底色、字号都走令牌）。要品牌语气就把按钮的类名写到触发器上，或改 <code>--xh-download-trigger-*</code> 这一族槽位。</li><li>与<a href="./progress">进度条</a>搭配：取数要跑很久时，自己在旁边放一条进度，本组件只报&quot;在途 / 结束&quot;两档。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>大文件走服务端直链，别在前端拼 Blob：整份内容会先住进内存，几十兆的导出足以让标签页卡住。</li><li>取数函数里自己兜住失败并给出可见提示，<code>onDownloadError</code> 只通知你，用户看到的还是那颗没反应的按钮。</li><li>文件名带扩展名。浏览器不会替你猜，<code>report</code> 与 <code>report.csv</code> 打开的方式完全不同。</li><li>换外观改 <code>--xh-download-trigger-*</code> 槽位，别只覆盖前景色：禁用态的底色也在这一族里，只改一半会把禁用前后压成同一个样子。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>认为回调触发就等于文件已经存好：组件只能知道下载已经发起，用户取消保存、磁盘写失败都在浏览器那一侧。</li><li>页面一加载就把整份数据备在内存里等着点：改成取数函数，点了再算。</li><li>用它下载跨域地址上的文件：浏览器发起的下载受同源与下载策略约束，跨域内容取不回来也就造不出 Blob。</li></ul>',48))])}const P=c(s,[["render",g]]);export{w as __pageData,P as default};
